        W("Corregir un puntaje", "Dos niños suman puntos. Mía anota 7 y por error su amigo anota 9 para ella. ¿Cuántos puntos de más le sumaron?",
          ["El puntaje correcto es 7.", "El anotado es 9.", "La diferencia es 9 − 7 = 2."], "2 puntos de más"),
